#!/usr/bin/env node
/**
 * Gói CSS global của User Web — nạp MỘT lần cho mọi trang (App Shell + DS + gói cũ đang chuyển dần).
 *
 *   node ui_tooling/scripts/build-web-bundle.mjs          → sinh platform/web/dist/web.css + cập nhật <link> trong User_Web/**.html
 *   node ui_tooling/scripts/build-web-bundle.mjs --check  → kiểm tra gói khớp nguồn + mọi trang trỏ đúng version (governance / CI)
 *
 * Gộp phẳng @import (theo thứ tự nguồn, file trùng chỉ lấy lần đầu), đổi url() tương đối thành đường dẫn tuyệt đối,
 * version = hash nội dung (?v=<hash>) → CDN không bao giờ trả bản cũ.
 * CSS riêng của trang KHÔNG nằm trong gói (khai báo trong manifest trang, nạp khi vào trang).
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = 'platform/web/dist/web.css';

/* Thứ tự = thứ tự cascade. DS (platform/web/web.css) trước gói cũ: tên trùng giữ giá trị cũ tới W4. */
const ENTRIES = [
  '/Admin_Design_system/iflux-admin-ui/fonts.css',
  '/platform/web/web.css',
  '/Admin_Design_system/iflux-admin-ui/iflux-admin-ui.css',
  '/User_Web/iflux-web-ui/app-shell.css'
];
/* Không đưa vào gói User Web: bộ icon cũ (DS đã có đủ icon User Web dùng — vendor/tabler). */
const EXCLUDE = new Set(['/Admin_Design_system/iflux-admin-ui/vendor/tabler-icons/tabler-icons.min.css']);
/* <link> cũ trong trang được thay bằng gói. */
const REPLACED_LINKS = /(Admin_Design_system\/iflux-admin-ui\/fonts\.css|platform\/web\/web\.css|Admin_Design_system\/iflux-admin-ui\/iflux-admin-ui\.css|iflux-web-ui\/app-shell\.css|platform\/web\/dist\/web\.css)/;

function webPath(from, ref) {
  const clean = ref.split('?')[0].split('#')[0];
  if (clean.startsWith('/')) return path.posix.normalize(clean);
  return path.posix.normalize(path.posix.join(path.posix.dirname(from), clean));
}

function flatten(web, seen, out) {
  if (seen.has(web) || EXCLUDE.has(web)) return;
  seen.add(web);
  const file = path.join(REPO, web);
  if (!fs.existsSync(file)) throw new Error('Thiếu file nguồn ' + web);
  let css = fs.readFileSync(file, 'utf8');
  /* url() tương đối → tuyệt đối (bỏ qua data:, http, #) */
  css = css.replace(/url\(\s*(['"]?)(?!data:|https?:|\/|#)([^'")]+)\1\s*\)/g, (m, q, u) => `url(${q}${webPath(web, u)}${q})`);
  const parts = [];
  let last = 0;
  for (const m of css.matchAll(/@import\s+url\(\s*['"]?([^'")]+)['"]?\s*\)\s*([^;]*);/g)) {
    parts.push(css.slice(last, m.index));
    if (m[2].trim()) throw new Error('@import có media chưa hỗ trợ: ' + m[0]);
    const child = webPath(web, m[1]);
    flatten(child, seen, out);
    last = m.index + m[0].length;
  }
  parts.push(css.slice(last));
  out.push(`/* ── ${web} ── */\n` + parts.join('').trim() + '\n');
}

function build() {
  const seen = new Set();
  const out = [];
  for (const e of ENTRIES) flatten(e, seen, out);
  const body = out.join('\n');
  const hash = crypto.createHash('sha256').update(body).digest('hex').slice(0, 10);
  const head = `/* DO NOT EDIT — GENERATED by ui_tooling/scripts/build-web-bundle.mjs\n * Gói CSS global User Web · ${seen.size - [...seen].filter((s) => EXCLUDE.has(s)).length} file nguồn · hash ${hash}\n * Nguồn: ${ENTRIES.join(' · ')}\n */\n`;
  return { css: head + body, hash };
}

function pages() {
  const res = [];
  const walk = (d) => {
    for (const n of fs.readdirSync(path.join(REPO, d))) {
      const rel = path.posix.join(d, n);
      const st = fs.statSync(path.join(REPO, rel));
      if (st.isDirectory()) walk(rel);
      else if (n.endsWith('.html')) res.push(rel);
    }
  };
  walk('User_Web');
  return res.filter((f) => /iflux-admin-ui\.css|platform\/web\/(dist\/)?web\.css/.test(fs.readFileSync(path.join(REPO, f), 'utf8')));
}

function rewritePage(html, hash) {
  const lines = html.split('\n');
  let indent = '  ';
  let at = -1;
  const keep = [];
  for (const line of lines) {
    const isLink = /<link\b[^>]*rel="stylesheet"/.test(line) && REPLACED_LINKS.test(line);
    const isNote = /<!-- Nền tảng User Web \(lưới DS \+ bố cục trang\)/.test(line) || /<!-- CSS global User Web/.test(line);
    if (isLink || isNote) {
      if (at < 0) { at = keep.length; indent = line.match(/^\s*/)[0]; }
      continue;
    }
    keep.push(line);
  }
  if (at < 0) return html;
  keep.splice(at, 0,
    `${indent}<!-- CSS global User Web (App Shell + DS) — một file, sinh bởi ui_tooling/scripts/build-web-bundle.mjs -->`,
    `${indent}<link rel="stylesheet" href="/${OUT}?v=${hash}" />`);
  return keep.join('\n');
}

const check = process.argv.includes('--check');
const { css, hash } = build();
const outFile = path.join(REPO, OUT);
const problems = [];
if (check) {
  if (!fs.existsSync(outFile) || fs.readFileSync(outFile, 'utf8') !== css) problems.push(`${OUT} không khớp nguồn — chạy lại build-web-bundle.mjs`);
} else {
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, css);
}
let changed = 0;
for (const f of pages()) {
  const file = path.join(REPO, f);
  const html = fs.readFileSync(file, 'utf8');
  const next = rewritePage(html, hash);
  if (next !== html) {
    if (check) problems.push(`${f} chưa trỏ đúng /${OUT}?v=${hash}`);
    else { fs.writeFileSync(file, next); changed++; }
  }
}
if (problems.length) {
  console.error('[build-web-bundle] FAIL\n  ' + problems.join('\n  '));
  process.exit(1);
}
console.log(`[build-web-bundle] ${check ? 'PASS' : 'OK'} — ${OUT} · ${(css.length / 1024).toFixed(0)} KB · v=${hash}${check ? '' : ` · ${changed} trang cập nhật`}`);
